bugRepair.brokenCode:
/* تصميم يعتمد على أبعاد بكسل ثابتة */
.main-layout {
  width: 960px;
  /* النتيجة: الموقع يظهر مقطوعاً ويجبر مستخدمي الهواتف على التمرير الأفقي البشع */
}

.card-grid {
  display: grid;
  /* المطور حدد 4 أعمدة ثابتة */
  grid-template-columns: repeat(4, 250px);
  /* النتيجة: الشبكة تفيض وتخرج عن شاشات الهواتف والأجهزة اللوحية */
}

/* محاولة تفعيل الوضع الداكن */
@media (color-scheme: dark) {
  body { background: #121212; color: #fff; }
}

img {
  width: 100%;
  /* النتيجة: تقفز النصوص للأسفل فجأة عند اكتمال تنزيل الصورة مما يربك القارئ (CLS) */
}

iframe.video {
  width: 560px;
  height: 315px;
  /* النتيجة: عند فتح الصفحة على هاتف بعرض 360px يخرج الفيديو عن الشاشة */
}

bugRepair.fixedCode:
iframe.video {
  width: 100%;
  max-width: 560px;
  aspect-ratio: 16 / 9;
  height: auto;
}

